UPDATE arr_digital_repository
SET digital_repository_type = 'FILESYSTEM'
WHERE external_system_id IN (
    SELECT external_system_id FROM sys_external_system WHERE url LIKE 'file://%'
);
UPDATE sys_external_system
SET url = SUBSTRING(url FROM 8)
WHERE url LIKE 'file://%';

INSERT INTO arr_legacy_dao_link (dao_link_id, dao_id, scenario)
SELECT dao_link_id, dao_id, scenario FROM arr_dao_link WHERE dao_id IS NOT NULL;
INSERT INTO arr_da_link (dao_link_id, aip_id, da_dao_id)
SELECT dao_link_id, aip_id, da_dao_id FROM arr_dao_link WHERE aip_id IS NOT NULL;
